-- Append to the scale migration in place of COMMIT. All fixtures roll back.
select set_config('request.jwt.claim.sub',(select id::text from auth.users where raw_app_meta_data->>'easycall_role'='super' order by created_at limit 1),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',auth.uid(),'aal','aal2')::text,true);
do $$ declare uid uuid:=auth.uid();original_meta jsonb;meta jsonb;v1 public.easycall_voters;v2 public.easycall_voters;r jsonb;entry jsonb;rev timestamptz;st timestamptz;blocked boolean:=false;
begin
 select raw_app_meta_data into original_meta from auth.users where id=uid;
 perform public.easycall_admin_save_camp(jsonb_build_object('campId','scale_test','name','Scale Test','candidate','Fixture','sido','서울특별시','city','중구','party','무소속','staff','Fixture','manager','Fixture','electionStage','본선','electionType','국회의원','tablets',2000,'unitPrice',0,'contractAmount',0,'startsOn',current_date-1,'endsOn',current_date+30),null,gen_random_uuid());
 update public.easycall_sync_store set payload=jsonb_set(payload,'{agentsList}',coalesce(payload->'agentsList','[]')||(select jsonb_agg(jsonb_build_object('campId','scale_test','agentId','device'||i,'assignedPhone','01000000000')) from generate_series(1,2000)i)),updated_at=clock_timestamp() where store_key='MASTER_META';
 update public.easycall_sync_store set payload=jsonb_set(payload,'{config}','{"nightLock":false,"globalStopped":false}'),updated_at=clock_timestamp() where store_key='STATE_scale_test';
 insert into public.easycall_voters(camp_id,voter_id,name,phone,last_result) select 'scale_test','v'||i,'Fixture','0100000000'||i,'READY' from generate_series(1,8)i;
 if (select count(*) from easycall_private_v2.agent_registry where camp_id='scale_test')<>2000 then raise exception 'indexed device mirror failed';end if;
 update auth.users set raw_app_meta_data=jsonb_build_object('easycall_role','agent','camp_id','scale_test','agent_id','device1') where id=uid;
 select * into v1 from public.easycall_claim_voter('scale_test');
 select * into v2 from public.easycall_claim_voter('scale_test');if v1.voter_id is distinct from v2.voter_id then raise exception 'duplicate claim changed lease';end if;
 r:=public.easycall_agent_control(null,'online',v1.voter_id);rev:=(r->>'revision')::timestamptz;
 if r->'agent'->>'agentId'<>'device1' or length(r::text)>10000 then raise exception 'control leaked full registry';end if;
 if public.easycall_agent_control(rev)->'config'<>'null'::jsonb then raise exception 'unchanged config resent';end if;
 perform public.easycall_authorize_call('scale_test',v1.voter_id);
 entry:=jsonb_build_object('call_id',gen_random_uuid(),'camp_id','scale_test','voter_id',v1.voter_id,'call_result','ABSENT','status','NONE','duration_seconds',0,'memo','Fixture');
 perform public.easycall_complete_call(entry);perform public.easycall_complete_call(entry);
 if (select count(*) from public.easycall_call_logs where camp_id='scale_test')<>1 then raise exception 'duplicate committed call';end if;
 if public.easycall_agent_control()->'ownCounts'->>'total'<>'1' then raise exception 'incremental counter mismatch';end if;
 r:=public.easycall_camp_counts('scale_test');if (r->'logs'->>'total')::int<>1 then raise exception 'count mismatch';end if;
 update auth.users set raw_app_meta_data=jsonb_build_object('easycall_role','agent','camp_id','scale_test','agent_id','device2') where id=uid;
 select * into v2 from public.easycall_claim_voter('scale_test');if v2.voter_id=v1.voter_id then raise exception 'another agent reused finished row';end if;
 begin perform public.easycall_complete_call(entry);raise exception 'another actor replayed call' using errcode='ZC002';exception when sqlstate 'P0001' then null;end;
 select updated_at into st from public.easycall_sync_store where store_key='STATE_scale_test';
 entry:=jsonb_build_object('call_id',gen_random_uuid(),'camp_id','scale_test','voter_id',v2.voter_id,'call_result','REJECT','duration_seconds',0);
 perform public.easycall_complete_call(entry);
 if (select updated_at from public.easycall_sync_store where store_key='STATE_scale_test') is distinct from st then raise exception 'DNC serialized global config';end if;
 insert into public.easycall_voters(camp_id,voter_id,name,phone,last_result) values('scale_test','new-copy','Fixture',v2.phone,'READY');
 if (select last_result from public.easycall_voters where camp_id='scale_test' and voter_id='new-copy')<>'REJECT' then raise exception 'import bypassed DNC';end if;
 r:=public.easycall_camp_counts('scale_test');if r->'logs'->'results'->>'REJECT'<>'1' or r->'logs'->'results'?'ABSENT' then raise exception 'cached agent isolation failed';end if;
 update public.easycall_sync_store set payload=jsonb_set(payload,'{config,globalStopped}','true'),updated_at=clock_timestamp() where store_key='STATE_scale_test';
 begin perform public.easycall_claim_voter('scale_test');raise exception 'stopped camp assigned contact' using errcode='ZC002';exception when sqlstate 'P0001' then null;end;
 update public.easycall_sync_store set payload=jsonb_set(payload,'{agentsList}',(select jsonb_agg(a) from jsonb_array_elements(payload->'agentsList')a where not(a->>'campId'='scale_test' and a->>'agentId'='device2'))),updated_at=clock_timestamp() where store_key='MASTER_META';
 begin perform public.easycall_agent_control();raise exception 'revoked device polled' using errcode='ZC002';exception when sqlstate 'P0001' then null;end;
 if has_function_privilege('authenticated','public.easycall_camp_counts_source_v4(text)','EXECUTE') or has_table_privilege('authenticated','easycall_private_v2.agent_registry','SELECT') then raise exception 'private data exposure';end if;
 update auth.users set raw_app_meta_data=original_meta where id=uid;
 perform public.easycall_admin_overview_fast(true);perform public.easycall_runtime_status();
end $$;
select 'PASS: 2000 indexed devices, compact control, lease reuse, replay, DNC, stop, revocation and cache isolation' as result;
rollback;
